"""Independently evaluated original corridors and free approaches.

The existing sweep constructors are shared verbatim with the repeat assembly.
Only neighbouring patch providers are dependencies. Sparse mouth results are
expanded to their original incidence indices; unused rows remain invalid.
"""
from types import SimpleNamespace
import bpy
from . import curved_junction_nodes as boundary,curved_network_surface_nodes as network
from . import curved_patch_provider_nodes as patches
from .curved_network_ownership_nodes import _compare,_total
c=boundary.c
PART='_cn_strip_part'
INDEX='_cn_strip_index'
KIND='_cn_strip_kind'


def _mouths(g,inp,*,transport_status=False):
    packed=inp.outputs['Patch Results']
    mouths=c._select(g,packed,_compare(g,c.named(g,patches.PART,'INT'),2))
    status=c._select(g,packed,_compare(g,c.named(g,patches.PART,'INT'),3))
    i=c.V(g,g.node('GeometryNodeInputIndex').outputs[0])
    original=c._store(g,inp.outputs['Approaches'],'st_cj_input_index',i,'INT')
    found,_=patches._lookup(g,mouths,'st_cj_input_index',i)
    missing=c._select(g,original,1.-found)
    missing=c._store(g,missing,'st_cj_valid',False,'BOOLEAN')
    order=g.node('GeometryNodeSortElements','Retain the original global mouth indices');order.domain='POINT'
    g.bind(boundary._join(g,missing,mouths),order.inputs['Geometry'])
    g.bind(c.named(g,'st_cj_input_index','INT'),order.inputs['Sort Weight'])
    at=c.named(g,'st_cj_input_index','INT')
    unique=_compare(g,_total(g,1,at),1)*_compare(g,at,0,'GREATER_EQUAL')*_compare(g,at,c._count(g,original),'LESS_THAN')
    valid=c._stat(g,mouths,unique)*g.math('GREATER_THAN',c._count(g,status),.5)
    valid=valid*_compare(g,c._count(g,order.outputs['Geometry']),c._count(g,original))
    metadata_valid=valid
    valid=valid*c._stat(g,status,c.named(g,'valid','BOOLEAN'))
    if transport_status:return order.outputs['Geometry'],valid,metadata_valid
    return order.outputs['Geometry'],valid


def build(*,retain_failures=False,interpolation=False):
    name='Prochitecture Streets / Cached original strip owner v2'
    if retain_failures:name+=' / Retain local failure records v1'
    if interpolation:name+=' / Exact or smooth v2 / Mixed seam frames'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name)
    for key in ('Sources','Mapping','Approaches','Corridors','External Approaches','Transitions','Patch Results'):
        g.socket(key,'NodeSocketGeometry')
    for key,value in (('Cell Size',1.),('Height Exaggeration',10.)):g.socket(key,'NodeSocketFloat',default=value)
    for key,value in (('Samples Per Side',129),('Relax Iterations',100),('Owner Index',0),('Owner Kind',1)):
        g.socket(key,'NodeSocketInt',default=value)
    g.socket('Geometry','NodeSocketGeometry','OUTPUT');g.socket('Valid','NodeSocketBool','OUTPUT')
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput');at=inp.outputs['Owner Index'];kind=inp.outputs['Owner Kind']
    mouths,valid,metadata_valid=_mouths(g,inp,transport_status=True)
    corridor=network.corridor_owner(g,inp,mouths,valid,at,dimensions=True,local_frames=True,port_paths=True,interpolation=interpolation)
    approach=network.external_owner(g,inp,mouths,valid,at,local_frames=True,port_paths=True,interpolation=interpolation)
    is_approach=_compare(g,kind,3)
    rows=c.choose(g,is_approach,inp.outputs['External Approaches'],inp.outputs['Corridors'],'GEOMETRY')
    within=_compare(g,at,0,'GREATER_EQUAL')*_compare(g,at,c._count(g,rows),'LESS_THAN')
    within=within*g.math('MINIMUM',1.,_compare(g,kind,1)+is_approach)
    parts=[c.choose(g,is_approach,a,b,'GEOMETRY') for a,b in zip(approach[:3],corridor)]
    parts.append(boundary._empty(g,approach[3],is_approach))
    parts[1]=c._store(g,parts[1],'valid',c.named(g,'valid','BOOLEAN')*within,'BOOLEAN')
    packed=[]
    for role,part in enumerate(parts,1):
        for key,value in ((PART,role),(INDEX,at),(KIND,kind)):part=c._store(g,part,key,value,'INT')
        packed.append(part)
    g.bind(boundary._join(g,*packed),out.inputs['Geometry'])
    g.bind((metadata_valid if retain_failures else valid)*within,out.inputs['Valid'])
    return g.g


def unpack(g,inp,*,require_geometry_valid=True):
    """Verify one strip for every declaration before the unchanged seam checks."""
    packed=inp.outputs['Strip Results'];results=[];valid=1.
    for kind,table_name,prefix,capacity in ((1,'Corridors','st_cs_',network.MAX_CORRIDORS),
                                           (3,'External Approaches','st_ca_',network.MAX_EXTERNAL_APPROACHES)):
        table=inp.outputs[table_name];n=c._count(g,table)
        parts={name:c._select(g,packed,_compare(g,c.named(g,PART,'INT'),role)*_compare(g,c.named(g,KIND,'INT'),kind))
               for role,name in enumerate(('Surfaces','Status','Diagnostics','End Ports'),1)}
        # Diagnostics use st_cs_end for a floating-point path distance, while
        # pavement uses the same name for the integer endpoint role -1/0/1.
        # Packing promotes that surface field to FLOAT. Restore its native
        # type before welding, otherwise seam averaging produces fractional
        # endpoint roles and changes downstream free-end/separator selection.
        parts['Surfaces']=c._store(g,parts['Surfaces'],'st_cs_end',c.named(g,'st_cs_end','INT'),'INT')
        status=parts['Status'];at=c.named(g,INDEX,'INT')
        good=_compare(g,at,0,'GREATER_EQUAL')*_compare(g,at,n,'LESS_THAN')*_compare(g,_total(g,1,at),1)
        good=good*_compare(g,c.named(g,'st_cn_owner','INT'),c._read(g,table,prefix+'street_id',at,'INT'))
        good=good*_compare(g,c.named(g,'st_cn_kind','INT'),kind)
        if require_geometry_valid:good=good*c.named(g,'valid','BOOLEAN')
        if kind==3:good=good*_compare(g,c.named(g,'st_ca_end_role','INT'),c._read(g,table,'st_ca_end_role',at,'INT'))
        valid=valid*_compare(g,c._count(g,status),n)*g.math('LESS_THAN',n,capacity+.5)
        valid=valid*c.choose(g,g.math('GREATER_THAN',n,.5),c._stat(g,status,good),1.)
        results.append(SimpleNamespace(outputs=parts))
    return *results,valid
